    /* Defines the inventory mode for the duplicated source product. This parameter supports two modes: SHARED and EXCLUSIVE.   - SHARED: In this mode, the inventory of all interconnected (shared) products must be strictly consistent; otherwise, an error will be returned. - EXCLUSIVE: In this mode, the inventory for each product can be set independently without affecting others.   Applicability: This feature is applicable ONLY for the EU market.   Default Value: If left empty, the system defaults to the EXCLUSIVE mode. */
    @SerializedName("inventory_mode")
    val inventoryMode: kotlin.String? = null,

    /* Legacy operations for enabling or disabling the `AUCTION` product tag. If `selling_format` is provided, it takes precedence over this field. */
    @SerializedName("product_tag_operations")
    val productTagOperations: kotlin.collections.List<ProductTagOperation>? = null,

    /* Purchase quantity limits applied to each SKU of the product, including the maximum quantity per order and the cumulative quantity across orders. */
    @SerializedName("purchase_order_quantity_limit")
    val purchaseOrderQuantityLimit: PurchaseOrderQuantityLimit? = null,

    /* Choose either Fixed price or Fixed price and LIVE auction. Fixed price is selected by default. LIVE auction require a starting bid price. Possible values: FIXED_PRICE, FIXED_PRICE_AND_LIVE_AUCTION. */
    @SerializedName("selling_format")
    val sellingFormat: EditProductRequest.SellingFormat? = null,

    /* false — NORMAL products true — LIVE_QUICK products. Only seller with the required permissions can creat LIVE_QUICK products. Default: false */
    @SerializedName("is_live_quick")
    val isLiveQuick: kotlin.Boolean? = null,

    /* Whether the product is a blind box of lucky bag. For example: PopMart */
    @SerializedName("is_blind_box")
    val isBlindBox: kotlin.Boolean? = null

) {

    /**
     * Indicates how the product should be saved. Possible values: - AS_DRAFT: Save the product as a draft for future editing. - LISTING: Submit the edited product for listing. Changes that require review are published after approval; changes to the price or inventory fields are published immediately. Default: LISTING  **Note**: - Saving as draft is not supported when the product status is `DELETED`, or when the product is `PENDING` or `FREEZE` on any listing platform. - When saving a post-live draft with `save_mode=AS_DRAFT`, `inventory` and `delivery_option_ids` are not supported and will not be saved.
     *
     * Values: AS_DRAFT,LISTING
     */
    enum class SaveMode(val value: kotlin.String) {
        @SerializedName(value = "AS_DRAFT") AS_DRAFT("AS_DRAFT"),
        @SerializedName(value = "LISTING") LISTING("LISTING");
    }
    /**
     * The platforms for listing the product. Possible values: - TOKOPEDIA - TIKTOK_SHOP Applicable only for sellers that migrated from Tokopedia.  **IMPORTANT**: This field controls the product's visibility on the listing platforms. - If the product is live on both platforms but the request contains only 1 platform, the product will be deactivated and hidden from the omitted platform. - If the product is live on 1 platform but the request contains a different platform, the product will be deactivated and hidden from the omitted platform. - If you omit this array, the product will be sent for audit on the currently active platforms or on the platforms specified in the previous request. - If you want to deactivate the product on both platforms, use the Deactivate Product API.
     *
     * Values: TOKOPEDIA,TIKTOK_SHOP
     */
    enum class ListingPlatforms(val value: kotlin.String) {
        @SerializedName(value = "TOKOPEDIA") TOKOPEDIA("TOKOPEDIA"),
        @SerializedName(value = "TIKTOK_SHOP") TIKTOK_SHOP("TIKTOK_SHOP");
    }
    /**
     * The shipping insurance purchase requirement imposed on buyers for the product.  Possible values: - REQUIRED: Shipping insurance is mandatory and buyers can't opt out. - OPTIONAL: Buyers can choose to purchase shipping insurance through the platform. - NOT_SUPPORTED: Shipping insurance is not supported for the product. Default: OPTIONAL  Applicable only if the listing platforms include TOKOPEDIA.
     *
     * Values: REQUIRED,OPTIONAL,NOT_SUPPORTED
     */
    enum class ShippingInsuranceRequirement(val value: kotlin.String) {
        @SerializedName(value = "REQUIRED") REQUIRED("REQUIRED"),
        @SerializedName(value = "OPTIONAL") OPTIONAL("OPTIONAL"),
        @SerializedName(value = "NOT_SUPPORTED") NOT_SUPPORTED("NOT_SUPPORTED");
    }
    /**
     * The BCP-47 locale codes for displaying category information. Default: The default locale of your shop. Possible values:  - `de-DE` - `en-GB` - `en-IE` - `en-US` - `es-ES` - `es-MX` - `fr-FR` - `id-ID` - `it-IT` - `ja-JP` - `ms-MY` - `pt-BR` - `th-TH` - `vi-VN` - `zh-CN`
     *
     * Values: deMinusDE,enMinusGB,enMinusIE,enMinusUS,esMinusES,esMinusMX,frMinusFR,idMinusID,itMinusIT,jaMinusJP,msMinusMY,ptMinusBR,thMinusTH,viMinusVN,zhMinusCN
     */
    enum class Locale(val value: kotlin.String) {
        @SerializedName(value = "de-DE") deMinusDE("de-DE"),
        @SerializedName(value = "en-GB") enMinusGB("en-GB"),
        @SerializedName(value = "en-IE") enMinusIE("en-IE"),
        @SerializedName(value = "en-US") enMinusUS("en-US"),
        @SerializedName(value = "es-ES") esMinusES("es-ES"),
        @SerializedName(value = "es-MX") esMinusMX("es-MX"),
        @SerializedName(value = "fr-FR") frMinusFR("fr-FR"),
        @SerializedName(value = "id-ID") idMinusID("id-ID"),
        @SerializedName(value = "it-IT") itMinusIT("it-IT"),
        @SerializedName(value = "ja-JP") jaMinusJP("ja-JP"),
        @SerializedName(value = "ms-MY") msMinusMY("ms-MY"),
        @SerializedName(value = "pt-BR") ptMinusBR("pt-BR"),
        @SerializedName(value = "th-TH") thMinusTH("th-TH"),
        @SerializedName(value = "vi-VN") viMinusVN("vi-VN"),
        @SerializedName(value = "zh-CN") zhMinusCN("zh-CN");
    }
    /**
     * Choose either Fixed price or Fixed price and LIVE auction. Fixed price is selected by default. LIVE auction require a starting bid price. Possible values: FIXED_PRICE, FIXED_PRICE_AND_LIVE_AUCTION.
     *
     * Values: FIXED_PRICE,FIXED_PRICE_AND_LIVE_AUCTION
     */
    enum class SellingFormat(val value: kotlin.String) {
        @SerializedName(value = "FIXED_PRICE") FIXED_PRICE("FIXED_PRICE"),
        @SerializedName(value = "FIXED_PRICE_AND_LIVE_AUCTION") FIXED_PRICE_AND_LIVE_AUCTION("FIXED_PRICE_AND_LIVE_AUCTION");
    }

}

